import math

def verify_triple(B, T, S, name):
    """
    Verifies if a triple (B, T, S) satisfies the near number definitions
    and the sum condition, returning the exponents (a, b, c) or None if invalid.
    B = 2^a + 1, T = 3^b + 1, S = 6^c + 1.
    """

    # 1. Check B = 2^a + 1
    try:
        two_pow_a = B - 1
        if two_pow_a <= 0 or (two_pow_a & (two_pow_a - 1) != 0):
            return None, f"B={B} is not a 2-near number (B-1={two_pow_a} is not a power of 2)."
        a = two_pow_a.bit_length() - 1
        if 2**a != two_pow_a: # Should not happen if the check above is right, but good practice
             return None, f"Error calculating 'a' for B={B}."
    except Exception as e:
        return None, f"Error processing B={B}: {e}"

    # 2. Check T = 3^b + 1
    try:
        three_pow_b = T - 1
        if three_pow_b <= 0:
            return None, f"T={T} is not a 3-near number (T-1={three_pow_b} is not positive)."
        b = round(math.log(three_pow_b, 3))
        if 3**b != three_pow_b:
            return None, f"T={T} is not a 3-near number (T-1={three_pow_b} is not a power of 3)."
    except ValueError:
        return None, f"Error processing T={T}: Logarithm undefined."
    except Exception as e:
        return None, f"Error processing T={T}: {e}"

    # 3. Check S = 6^c + 1
    try:
        six_pow_c = S - 1
        if six_pow_c <= 0 or (six_pow_c & (six_pow_c - 1) != 0 and six_pow_c != 0): # This is insufficient, check actual powers of 6
            c = 0
            current_power = 1
            while current_power < six_pow_c:
                current_power *= 6
                c += 1
            if current_power != six_pow_c:
                return None, f"S={S} is not a 6-near number (S-1={six_pow_c} is not a power of 6)."
        else:
            c = 0
            current_power = 1
            while current_power < six_pow_c:
                current_power *= 6
                c += 1
    except Exception as e:
        return None, f"Error processing S={S}: {e}"


    # 4. Confirm sum B + T = S
    sum_check = (B + T == S)

    if sum_check:
        return (a, b, c), f"SUCCESS: B+T=S ({B}+{T}={S}). Exponents: a={a}, b={b}, c={c}."
    else:
        return None, f"FAILURE: B+T != S ({B}+{T}={B+T}, expected {S})."

triples = {
    "Triple 1 (3, 4, 7)": (3, 4, 7),
    "Triple 2 (33, 4, 37)": (33, 4, 37),
    "Triple 3 (9, 28, 37)": (9, 28, 37),
}

results = {}
total_sum = 0
print("--- Verification Results ---")

for name, (B, T, S) in triples.items():
    result, message = verify_triple(B, T, S, name)
    results[name] = result
    print(f"\nVerification for {name}:")
    print(f"  {message}")

    if result:
        total_sum += (B + T + S)

print("\n===============================")
print(f"Final Calculated Sum of (B+T+S): {total_sum}")
